mapper.select:
SELECT stock_code AS symbol, company_name AS name, market_type AS market, dart_corp_code
FROM company
WHERE stock_code = #{symbol}

SELECT report_id, stock_code, receipt_no, business_year, report_code, fs_div, collected_at
FROM financial_report
WHERE receipt_no = #{receiptNo}
  AND fs_div = #{fsDiv}

SELECT report_id, stock_code, receipt_no, business_year, report_code, fs_div, collected_at
FROM financial_report
WHERE stock_code = #{stockCode}
  AND business_year = #{businessYear}
  AND report_code = #{reportCode}
ORDER BY receipt_no DESC

SELECT value_id, report_id, account_code, account_name, source_account_id, source_account_name, current_amount, previous_amount, currency, value_status
FROM financial_value
WHERE report_id = #{reportId}
